sp_widget.css:
.cp-hero { background:
  radial-gradient(1200px 400px at 80% -10%, rgba(20,184,166,.08), transparent 60%),
  var(--cp-bg);
  border-bottom: 1px solid var(--cp-line); }
.cp-hero__wrap { max-width: 1120px; margin: 0 auto; padding: 56px 28px 44px; }
.cp-hero__grid { display: grid; grid-template-columns: minmax(0,1fr) 300px; gap: 44px; align-items: end; }
.cp-hero__title { font-size: 44px; line-height: 1.05; font-weight: 850; letter-spacing: -.02em; margin: 0 0 16px; }
.cp-hero__title span { color: var(--cp-gold); }
.cp-hero__copy { color: var(--cp-muted); font-size: 17px; max-width: 520px; margin: 0 0 26px; }
.cp-hero__actions { display: flex; gap: 12px; flex-wrap: wrap; }
.cp-hero__note { background:#fff; border:1px solid var(--cp-line); border-radius:14px;
  padding:20px; font-size:14px; color:var(--cp-muted); box-shadow: var(--cp-card-shadow); }
.cp-hero__note strong { display:block; color:var(--cp-navy); margin-bottom:6px; font-size:15px; }
.cp-hero__life { display:flex; flex-wrap:wrap; gap:8px; margin-top:38px; padding-top:18px; border-top:1px solid var(--cp-line); }
.cp-hero__life span { display:inline-flex; align-items:center; min-height:30px; padding:0 12px;
  border-radius:999px; background:#fff; border:1px solid var(--cp-line); color:var(--cp-muted);
  font-size:12px; font-weight:750; }
.cp-hero__life span.is-first { border-color: rgba(20,184,166,.45); color:#08796F; }
@media (max-width:820px){
  .cp-hero__wrap{ padding:34px 18px 30px; }
  .cp-hero__grid{ grid-template-columns:1fr; gap:26px; }
  .cp-hero__title{ font-size:34px; }
  .cp-btn{ width:100%; }
}

sp_widget.script:
(function() {
  data.firstName = gs.getUser().getFirstName() || '';
  // record producer sys_id for the Submit CTA
  data.submitHref = '?id=sc_cat_item&sys_id=18a0bcf7c30147d0b68cd50d05013103';
  data.lifecycle = ['New','Under Review','Investigation','Approved','Rejected','Closed'];
})();
